INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '应用题', 2, '{"stem": "动物园里有16只熊猫，天鹅的只数是熊猫的3倍。天鹅有多少只？", "options": null}', '48只', '求一个数的几倍是多少用乘法：16×3=48（只）。答：天鹅有48只。', 'paper', '["practice", "ykl3sx", "4.8"]', '["paper_png/ykl3_sx/p082.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '应用题', 2, '{"stem": "乐乐今年5岁。爷爷今年的年龄是乐乐的12倍，爷爷今年多少岁？爷爷比乐乐大多少岁？", "options": null}', '60岁；55岁', '爷爷的年龄是乐乐的12倍：5×12=60（岁）；爷爷比乐乐大：60-5=55（岁）。答：爷爷今年60岁，比乐乐大55岁。', 'paper', '["practice", "ykl3sx", "4.8"]', '["paper_png/ykl3_sx/p082.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '应用题', 3, '{"stem": "小华家有31本故事书，文艺书的本数比故事书少3本，科技书的本数是文艺书的3倍，科技书有多少本？", "options": null}', '84本', '先算文艺书：31-3=28（本）；科技书是文艺书的3倍：28×3=84（本）。答：科技书有84本。', 'paper', '["practice", "ykl3sx", "4.8"]', '["paper_png/ykl3_sx/p082.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '应用题', 3, '{"stem": "玫瑰花有145朵，月季花的朵数是玫瑰花的3倍，月季花有多少朵？玫瑰花和月季花一共有多少朵？", "options": null}', '435朵；580朵', '月季花是玫瑰花的3倍：145×3=435（朵）；一共：435+145=580（朵）。答：月季花有435朵，玫瑰花和月季花一共有580朵。', 'paper', '["practice", "ykl3sx", "4.8"]', '["paper_png/ykl3_sx/p082.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '应用题', 2, '{"stem": "兔子灯有34盏，球形灯的盏数是兔子灯的3倍。兔子灯和球形灯一共有（　）盏。想一想两种算法：算法一，先算球形灯的盏数，再算一共的盏数；算法二，先算一共是几个34盏。", "options": null}', '136；算法一：34×3=102，34+102=136（盏）；算法二：3+1=4，34×4=136（盏）', '算法一：先算球形灯34×3=102（盏），一共34+102=136（盏）；算法二：兔子灯是1份，球形灯是3份，一共是3+1=4份，34×4=136（盏）。答：一共有136盏。', 'paper', '["practice", "ykl3sx", "4.8"]', '["paper_png/ykl3_sx/p083.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '应用题', 2, '{"stem": "兔子灯有34盏，球形灯的盏数是兔子灯的3倍。球形灯比兔子灯多（　）盏。想一想两种算法：算法一，先算球形灯的盏数，再算多的盏数；算法二，先算球形灯比兔子灯多几个34盏。", "options": null}', '68；算法一：34×3=102，102-34=68（盏）；算法二：3-1=2，34×2=68（盏）', '算法一：球形灯34×3=102（盏），多102-34=68（盏）；算法二：球形灯比兔子灯多3-1=2份，34×2=68（盏）。答：多68盏。', 'paper', '["practice", "ykl3sx", "4.8"]', '["paper_png/ykl3_sx/p083.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '应用题', 3, '{"stem": "卡车有10辆，轿车的辆数是卡车的7倍少5辆，轿车有多少辆？（画线段图分析：先画1份表示卡车的10辆，轿车画这样的7份再少5辆）", "options": null}', '65辆', '轿车的辆数是卡车的7倍：10×7=70（辆），少5辆：70-5=65（辆）。答：轿车有65辆。', 'paper', '["practice", "ykl3sx", "4.8"]', '["paper_png/ykl3_sx/p083.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '应用题', 3, '{"stem": "学校图书馆有文艺书48本，故事书的本数是文艺书的3倍多15本，故事书有多少本？", "options": null}', '159本', '故事书是文艺书的3倍：48×3=144（本），多15本：144+15=159（本）。答：故事书有159本。', 'paper', '["practice", "ykl3sx", "4.8"]', '["paper_png/ykl3_sx/p083.png"]', 0);
